macro_rules! define_entity_table {
    ($($variant:ident => $table_name:expr),+) => {
        #[derive(Debug, Clone, Copy, PartialEq, Eq)]
        pub enum EntityTable { $($variant,)+ }
        ...
    };
}
define_entity_table! {
    Workspaces => "workspaces",
    Sessions => "sessions",
    RetrievalSnapshots => "retrieval_snapshots",
    ... // 18 total
}

pub(crate) fn get_insert_sql(table: EntityTable) -> &'static str {
    static INSERT_SQLS: [OnceLock<String>; ENTITY_TABLE_COUNT] = [const { OnceLock::new() }; ...];
    INSERT_SQLS[idx].get_or_init(|| INSERT_SQL_TEMPLATE.replace("{table}", table.table_name()))
}

pub fn save_entity<T: Serialize>(&self, table: EntityTable, id: &str, ...) -> Result<(), AppError> {
    let sql = get_insert_sql(table);
    conn.execute(sql, params![...])?;
}

